-- PinWith 공식 계정(@pinwith) 리스트(en). 이미 있으면 건너뛴다. 장소 id·좌표는 구글 장소 검색 결과(2026-10-17).
do $seed$
declare
  o uuid := (select id from public.profiles where handle = 'pinwith');
  doc jsonb := $json$[{"slug":"seoul-first-3-days","title":"Seoul for First-Timers: 3 Days from Palaces to the Han River","desc":"A first trip to Seoul, in an order that actually works on foot and by subway. Day 1 is old Seoul, Day 2 is markets and the downtown skyline, Day 3 is Gangnam and the river at night.\nTap a day to see only that day's pins on the map.","kind":"course","themes":["Seoul","First trip","3 days","Itinerary"],"sections":[{"name":"Day 1 · Old Seoul","items":[["ChIJod7tSseifDUR9hXHLFNGMIs",37.579617,126.977041,"Gyeongbokgung Palace","Start here at opening time. Entry is free if you wear hanbok (rental shops line the streets around the palace). Closed on Tuesdays.",["Closed Tue","Hanbok = free"]],["ChIJT8H4r9qifDURmuXJ_6m6vM0",37.5814696,126.9849519,"Bukchon Hanok Village","A 15-minute walk uphill from the palace. People live here, so keep your voice down and visit during the posted visiting hours.",["Quiet please"]],["ChIJR2GkpsKifDURh6X4t1FUx1Y",37.5732841,126.9856063,"Insadong-gil","Tea houses, paper shops and souvenir stalls. Good spot for an unhurried lunch.",["Souvenirs"]],["ChIJe4Jbot2ifDUR2zWhruwyaow",37.5737132,126.9901271,"Ikseon-dong","Narrow hanok alleys turned into cafés and small restaurants. Prettiest when the lights come on.",["Evening"]],["ChIJm3V0fu2ifDURRJ8IMUijVtY",37.5700385,126.9996038,"Gwangjang Market","Dinner: mung bean pancakes (bindaetteok), yukhoe (beef tartare) and mayak gimbap at the stalls. Bring some cash.",["Cash","Street food"]]]},{"name":"Day 2 · Markets & Downtown","items":[["ChIJIwCT4-yifDUR1E63iG76hr0",37.5691015,126.9786692,"Cheonggyecheon Stream","Walk the stream path east from Cheonggye Plaza. A calm start before the busy part of the day.",["Walk","Free"]],["ChIJW7FBDfCifDURHTpisLbVUH0",37.5610151,126.9860829,"Myeongdong Kyoja","Kalguksu (knife-cut noodle soup) and dumplings. The kimchi is very garlicky, and extra noodles are on the house.",["Lunch"]],["ChIJqWqOqFeifDURpYJ5LnxX-Fw",37.5511694,126.9882266,"N Seoul Tower","Go up in the late afternoon and stay for sunset and the city lights. Cable car or bus up, walk down through Namsan Park.",["Sunset","Views"]],["ChIJ8xRYr29FezUR3AtFqx2pIlw",37.5665256,127.0092236,"Dongdaemun Design Plaza","Zaha Hadid's curved building. Free to walk around; exhibitions inside vary.",["Architecture"]]]},{"name":"Day 3 · Gangnam & the River","items":[["ChIJgZn6QWmkfDURaU3kwlecaEU",37.514852,127.0573766,"Bongeunsa Temple","A working Buddhist temple right across from COEX. Peaceful in the morning.",["Free","Morning"]],["ChIJu5Gg2hWkfDURl7NN7FpFnis",37.5102133,127.0600186,"Starfield Library","The towering bookshelves inside COEX Mall. Free to enter; it gets busy in the afternoon.",["Free","Indoor"]],["ChIJu7dpc45FezURhLMS5U5eaJk",37.5125295,127.102305,"Seoul Sky (Lotte World Tower)","Observation deck near the top of the 123-floor tower. Pick a clear day; tickets are cheaper online.",["Tickets","Views"]],["ChIJeVnK5X-hfDURv2fEEK-332M",37.5126335,126.9984783,"Banpo Bridge Moonlight Rainbow Fountain","End at the river. The fountain show runs in the warmer months in the evening — check show times before you go.",["Night","Seasonal"]]]}]},{"slug":"seoul-markets-street-food","title":"Seoul Markets & Street Food: Eat Like a Local","desc":"Seoul's traditional markets are where you eat best for the least money. Morning markets are calmer and more local; the evening ones are louder and more fun.\nMost stalls prefer cash or Korean cards, so carry some won.","kind":"collection","themes":["Seoul","Street food","Markets","Budget"],"sections":[{"name":"Daytime markets","items":[["ChIJYxd6fL6ifDURy7wm894BUcQ",37.5807649,126.9706756,"Tongin Market","Buy brass coins at the lunchbox café, then fill a tray from different stalls. Try the oil tteokbokki.",["Lunchbox","Cash"]],["ChIJA6gxryiZfDURJvmbeBvdz_Y",37.5559018,126.9062854,"Mangwon Market","A neighbourhood market, not a tourist one. Croquettes, fried chicken and fresh fruit — then carry it to the river.",["Local","Picnic"]],["ChIJfYjlFvWifDURYSDsoxYbN80",37.559277,126.9777029,"Namdaemun Market","Korea's biggest traditional market. Kalguksu alley and hotteok stalls. Closed on Sundays.",["Closed Sun"]]]},{"name":"Evening & night","items":[["ChIJm3V0fu2ifDURRJ8IMUijVtY",37.5700385,126.9996038,"Gwangjang Market","Bindaetteok fried to order, yukhoe and mayak gimbap. Sit at a counter and point.",["Cash","Must-try"]],["ChIJ_TLjgiSjfDURnctlL07vfJo",37.5703627,127.0057612,"Dakhanmari Alley","Whole chicken boiled at the table. Finish with noodles in the broth.",["Sharing"]],["ChIJqb-ne_CifDURR-yH8a3sjXM",37.5616685,126.9858438,"Myeongdong Night Market","Stalls open from late afternoon. Touristy and pricier, but a fun place to graze.",["Night","Touristy"]]]}]},{"slug":"seoul-rainy-day","title":"Rainy Day in Seoul: Museums, a Giant Library & Cozy Cafés","desc":"Everything here is indoors (or close to it). Mix one museum with one café and you have a good rainy day.","kind":"collection","themes":["Seoul","Rainy day","Museums","Cafés"],"sections":[{"name":"Museums","items":[["ChIJN2x0fu2ifDUR51BupseGYmE",37.5238506,126.9804702,"National Museum of Korea","Free permanent collection and you could spend a whole day. Open late on Wednesdays and Saturdays.",["Free","Half day+"]],["ChIJU97c4xujfDURu6F4mICL7Ps",37.5379389,126.9992749,"Leeum Museum of Art","Korean ceramics next to modern art, in striking buildings. Closed on Mondays; book exhibitions ahead.",["Closed Mon","Booking"]],["ChIJ5foyH5KifDURV-Z2f8Q71MY",37.5702678,126.9705277,"Seoul Museum of History","How Seoul grew, with a huge scale model of the city. Free, closed on Mondays.",["Free","Closed Mon"]]]},{"name":"Indoor wandering","items":[["ChIJu5Gg2hWkfDURl7NN7FpFnis",37.5102133,127.0600186,"Starfield Library","Free, enormous and very photogenic. Combine with lunch inside COEX Mall.",["Free"]],["ChIJ8xRYr29FezUR3AtFqx2pIlw",37.5665256,127.0092236,"Dongdaemun Design Plaza","Exhibitions and design shops under one curved roof.",["Design"]]]},{"name":"Cafés to wait out the rain","items":[["ChIJO_uFm7OjfDURH3ULjJYYuKg",37.5361018,127.000136,"Anthracite Hannam","A big, quiet roastery café. Good for reading or working for an hour.",["Roastery"]],["ChIJLXL2BvijfDURmTrYFPQIGUc",37.5776235,126.9865541,"Onion Anguk","Bakery café in a traditional hanok. Sit by the courtyard and watch the rain on the roof tiles.",["Hanok","Bakery"]]]}]},{"slug":"vlog-48h-west-seoul","title":"VLOG · 48 Hours in West Seoul: Hongdae, Yeonnam & a Han River Sunset","desc":"Written like a travel vlog: each section is an 'episode' and the notes read like a shot list.\nPinWith lets every place link to a moment in a YouTube video — if you film this route, add your own timestamps and share the list instead of a long description box.","kind":"course","themes":["Seoul","Vlog","Hongdae","Han River","48 hours"],"sections":[{"name":"Ep.1 · Arrival night in Hongdae","items":[["ChIJ68AiKsWYfDUROpTctLKtxtU",37.5561973,126.9250341,"Hongdae Street","▶ Opening shot: buskers and dance crews on the walking street after dark. B-roll of neon signs, then grab street snacks on camera.",["Night","Buskers"]]]},{"name":"Ep.2 · Slow morning in Yeonnam","items":[["ChIJH5tDs-WYfDURJGb8yuqKRwg",37.5662075,126.9192364,"Gyeongui Line Forest Park (Yeonnam)","▶ Morning walk on the old railway line turned park. Wide shot down the path, then cut to coffee from one of the cafés along it.",["Morning","Walk"]],["ChIJA6gxryiZfDURJvmbeBvdz_Y",37.5559018,126.9062854,"Mangwon Market","▶ Market lunch montage: croquettes, kalguksu, fruit cups. Ask before filming the vendors.",["Lunch","Local"]]]},{"name":"Ep.3 · River sunset","items":[["ChIJkfry2i-ZfDURdkxPeBp8x7Q",37.5527919,126.8985613,"Mangwon Hangang Park","▶ Golden hour: this stretch of the river faces the sunset. Time-lapse the bridge lights coming on.",["Sunset","Time-lapse"]],["ChIJ77fEAzuffDURLEWNv56G2KQ",37.5267106,126.9347112,"Yeouido Hangang Park","▶ Closing scene: convenience-store ramyeon by the river — the classic Seoul night picnic. Mats can be rented in the park.",["Night picnic"]]]}]},{"slug":"busan-weekend","title":"Busan Weekend: Beaches, Markets & a Cliffside Village","desc":"Busan splits neatly into two halves. Day 1 stays on the east coast (Haeundae and Gwangalli); Day 2 crosses to the old port side for markets and hillside villages.","kind":"course","themes":["Busan","Weekend","Beach","Itinerary"],"sections":[{"name":"Day 1 · East coast","items":[["ChIJXwf-DlyNaDURmKxjwdWxY5k",35.1586975,129.1603842,"Haeundae Beach","Morning walk along the sand to Dongbaek Island.",["Morning"]],["ChIJfdIYWwuNaDURDx-eqtUjCkg",35.158284,129.1727672,"Haeundae Blueline Park (Mipo)","Coastal beach train or the little Sky Capsules. Capsules sell out — book ahead.",["Book ahead"]],["ChIJwabeuxuMaDURXC4Rb21AQaE",35.1884543,129.2231109,"Haedong Yonggungsa Temple","A temple on the rocks by the sea. Go early; weekends are crowded.",["Early"]],["ChIJxw7HJy_taDUR-xaSTeHwbf8",35.1531696,129.118666,"Gwangalli Beach","Watch Gwangan Bridge light up after sunset.",["Night view"]],["ChIJix8ZnTPtaDURA4tBnQ6w9PM",35.1541919,129.1270348,"Millac the Market","Indoor food market at the end of Gwangalli with a view of the bridge. Easy dinner.",["Dinner"]]]},{"name":"Day 2 · Old port & hills","items":[["ChIJudkrFArpaDURbbCzajeQs0c",35.0966339,129.0307965,"Jagalchi Fish Market","Pick seafood downstairs, have it prepared at the restaurants upstairs.",["Seafood"]],["ChIJL1scg6DpaDURxXQZg1kWGZ4",35.098243,129.029212,"BIFF Square","Busan's street-food street. Get the seed hotteok (ssiat hotteok).",["Street food"]],["ChIJfYLMelSTaDURFlCRfk5W1PA",35.1013575,129.0281978,"Gukje Market","Wander the covered alleys; try bibim dangmyeon, Busan's cold glass-noodle snack.",["Market"]],["ChIJUToRo7fpaDURo_ZMItcBfpc",35.0973935,129.0105921,"Gamcheon Culture Village","Colourful hillside houses. Buy the stamp map and follow it. Comfortable shoes!",["Hills","Stamp map"]],["ChIJseGsfh7paDURigYilgTVojA",35.0782798,129.0453198,"Huinnyeoul Culture Village","A cliffside lane over the sea with small cafés — best in the late afternoon light.",["Sunset"]]]},{"name":"If you have extra time","items":[["ChIJOfX1e0zpaDURWq5Hp5x4-SM",35.05307,129.0872,"Taejongdae","Cliffs and lighthouse at the tip of Yeongdo. The Danubi tourist train saves your legs.",["Nature"]],["ChIJYeuKwGTraDUR-U5PAfT2Uoo",35.155399,129.0673266,"Jeonpo Café Street","Busan's café-and-vintage-shop neighbourhood for a slow evening.",["Cafés"]]]}]},{"slug":"jeju-2-days","title":"Jeju in 2 Days: Volcano Sunrise, Lava Caves & Black Pork","desc":"Jeju is bigger than it looks, so this route stays on one side per day. You will want a rental car (Korea requires an International Driving Permit for most visitors).","kind":"course","themes":["Jeju","2 days","Nature","Road trip"],"sections":[{"name":"Day 1 · East & volcanoes","items":[["ChIJn3jj9rkUDTURS7YjOgUyUVU",33.458056,126.9425,"Seongsan Ilchulbong","UNESCO-listed tuff cone. Climb for sunrise if you can; it is about 20–30 minutes up.",["Sunrise","UNESCO"]],["ChIJA_du00wVDTURisfAXXmN2fQ",33.5042977,126.954048,"Udo Island","Ferry from Seongsan port, then rent an e-bike to loop the island. Check ferry times in bad weather.",["Ferry"]],["ChIJmWohlsQZDTURppUrDPCrZrs",33.5281972,126.7717618,"Manjanggul Lava Tube","About 1 km of a huge lava tunnel is open. It stays cool inside all year — bring a jacket.",["Jacket","Cave"]],["ChIJxR5oOuwXDTUR7OVyfNv5QT4",33.5559739,126.7961709,"Woljeongri Beach","Clear turquoise water and windmills, lined with cafés.",["Beach","Cafés"]],["ChIJVSv3qq_8DDURcLh4pWxZ0vA",33.5434231,126.6697752,"Hamdeok Beach","White sand and shallow water — a good sunset stop on the way back to Jeju City.",["Sunset"]]]},{"name":"Day 2 · Forest, tea & the west coast","items":[["ChIJISh-Xu0DDTUROxfzWeIn6Qg",33.3949678,126.6839679,"Saryeoni Forest Path","Cedar forest walk. Lovely even (especially) in light rain.",["Forest","Walk"]],["ChIJhYbR5ZdTDDURtgGb2uZzuA0",33.246944,126.554417,"Cheonjiyeon Waterfall","Short, flat walk to the falls in Seogwipo. Lit up in the evening.",["Easy walk"]],["ChIJEczrGRJdDDUR0cpD2okSp7g",33.3059385,126.2894355,"O'sulloc Tea Museum","Green tea fields and matcha desserts.",["Tea"]],["ChIJ8bBzwwBhDDURAISiRyzO4mw",33.3942945,126.2398813,"Hyeopjae Beach","Emerald water with Biyangdo island on the horizon.",["Beach"]],["ChIJFfbe5lbjDDUR3WjCTurWe20",33.5154245,126.5268573,"Black Pork Street","Dinner: Jeju black pork grilled at the table. Many restaurants in a row — pick one with a crowd of locals.",["Dinner"]]]},{"name":"For hikers","items":[["ChIJoWNuAQABDTURc8w9j4nAo_o",33.3846218,126.6187151,"Seongpanak Trail (Hallasan)","The summit hike needs an online reservation, and there are cut-off times at the checkpoints. Start very early.",["Reservation","Full day"]]]}]},{"slug":"tokyo-first-4-days","title":"Tokyo, First Time: 4 Days Without Running Around","desc":"Tokyo is huge. This plan groups each day by area so you spend time in places, not on trains.","kind":"course","themes":["Tokyo","Japan","First trip","4 days"],"sections":[{"name":"Day 1 · Asakusa & Ueno","items":[["ChIJ8T1GpMGOGGARDYGSgpooDWw",35.7147651,139.7966553,"Senso-ji","Tokyo's oldest temple. Arrive before 8 a.m. to see it without crowds.",["Early"]],["ChIJ35ov0dCOGGARKvdDH7NPHX0",35.7100627,139.8107004,"Tokyo Skytree","A short hop from Asakusa. On a clear day you may see Mt Fuji.",["Views"]],["ChIJh7eDrwCPGGARCs9fpCkKS2U",35.7100682,139.7746009,"Ameyoko","Busy market street under the train tracks — snacks, fruit sticks and cheap finds.",["Street food"]],["ChIJPYwFnNGNGGARYEeXwiYQPe8",35.7276965,139.7657226,"Yanaka Ginza","Old-Tokyo shopping street. Most shops open late morning.",["Old Tokyo"]]]},{"name":"Day 2 · Harajuku & Shibuya","items":[["ChIJ5SZMmreMGGARcz8QSTiJyo8",35.6763976,139.6993259,"Meiji Jingu","Forest shrine next to Harajuku station.",["Free"]],["ChIJK9EM68qLGGARacmu4KJj5SA",35.659482,139.7005596,"Shibuya Scramble Crossing","Cross it once, then watch it from above.",["Iconic"]],["ChIJ4Rr2JWiLGGARcyRSHuZ-9G8",35.6586719,139.7019848,"Shibuya Sky","Rooftop deck over the crossing. Book a sunset slot in advance.",["Book ahead","Sunset"]],["ChIJOWucdKiMGGARbppa4b4CKA8",35.6611185,139.7009846,"Ichiran Shibuya","Tonkotsu ramen in solo booths, open late.",["Late night"]]]},{"name":"Day 3 · Tsukiji & the bay","items":[["ChIJW2cLzSGLGGARXAKXv6EkbqI",35.6647703,139.7702515,"Tsukiji Outer Market","Breakfast of tamagoyaki, tuna and skewers. Go early and bring cash.",["Cash","Breakfast"]],["ChIJSeco5wiJGGARItbTS8lQ5G0",35.6491207,139.7897739,"teamLab Planets","Immersive art you walk through barefoot, partly in water — wear clothes you can roll up. Timed tickets.",["Book ahead"]],["ChIJVVVp3BaJGGARfAgSR2yEybw",35.6777557,139.8005894,"Blue Bottle Coffee Kiyosumi-Shirakawa","The brand's first café in Japan, in a quiet warehouse district.",["Coffee"]]]},{"name":"Day 4 · West side","items":[["ChIJPyOTG8KMGGARh_IXobWxHmo",35.6851763,139.7100517,"Shinjuku Gyoen","Japanese, French and English gardens in one park. Small entry fee; closed on Mondays.",["Closed Mon"]],["ChIJw_teZ_8hGGARgsSeLR2OLjM",35.665786,139.6698627,"Shimokitazawa","Vintage shops, record stores and coffee.",["Vintage"]],["ChIJVVUBmZ_zGGARrEy-Ua3psAY",35.6488124,139.647481,"Gotokuji Temple","The temple of thousands of white beckoning cats (maneki-neko).",["Cats"]],["ChIJP9eKBdeMGGAR0zzBXJNVj5A",35.6927037,139.6995778,"Omoide Yokocho","Smoky yakitori alley by Shinjuku station. Tiny counters, so go in twos.",["Yakitori","Night"]]]}]},{"slug":"tokyo-ramen-late-night","title":"Tokyo Ramen & Late-Night Eats","desc":"Bowls and alleys worth queuing for. Ramen shops usually use a ticket machine at the door: pay first, hand over the ticket, sit.","kind":"collection","themes":["Tokyo","Ramen","Night","Food"],"sections":[{"name":"Ramen","items":[["ChIJ508frs-MGGARnIKrb_tkai0",35.6868343,139.6966393,"Fuunji","Rich chicken-and-fish tsukemen (dipping noodles). The line moves fast.",["Tsukemen","Queue"]],["ChIJOWucdKiMGGARbppa4b4CKA8",35.6611185,139.7009846,"Ichiran Shibuya","Tonkotsu in a private booth; you choose spice and firmness on a paper form.",["Solo-friendly"]]]},{"name":"Alleys & markets","items":[["ChIJP9eKBdeMGGAR0zzBXJNVj5A",35.6927037,139.6995778,"Omoide Yokocho","Yakitori and beer in a lantern-lit alley.",["Yakitori"]],["ChIJh7eDrwCPGGARCs9fpCkKS2U",35.7100682,139.7746009,"Ameyoko","Street snacks and izakaya under the tracks.",["Izakaya"]],["ChIJW2cLzSGLGGARXAKXv6EkbqI",35.6647703,139.7702515,"Tsukiji Outer Market","For the morning after: sushi, tamagoyaki, grilled seafood.",["Morning"]]]}]}]$json$::jsonb;
  rec jsonb; sec jsonb; it jsonb; lid uuid; sid uuid; pos int; si int;
begin
  for rec in select * from jsonb_array_elements(doc) loop
    continue when exists (select 1 from public.lists where owner_id = o and slug = rec->>'slug');
    insert into public.lists (owner_id, slug, title, description, visibility, kind, themes)
    values (o, rec->>'slug', rec->>'title', rec->>'desc', 'public', (rec->>'kind')::public.list_kind,
            array(select jsonb_array_elements_text(rec->'themes')))
    returning id into lid;
    pos := 0; si := 0;
    for sec in select * from jsonb_array_elements(rec->'sections') loop
      sid := null;
      if sec->>'name' is not null then
        insert into public.sections (list_id, name, position) values (lid, sec->>'name', si) returning id into sid;
      end if;
      for it in select * from jsonb_array_elements(sec->'items') loop
        insert into public.places (google_place_id, lat, lng, coords_fetched_at)
        values (it->>0, (it->>1)::float8, (it->>2)::float8, now()) on conflict (google_place_id) do nothing;
        insert into public.list_items (list_id, section_id, place_id, position, added_by, custom_title, memo, tags)
        values (lid, sid, it->>0, pos, o, it->>3, it->>4, array(select jsonb_array_elements_text(it->5)));
        pos := pos + 1;
      end loop;
      si := si + 1;
    end loop;
  end loop;
end $seed$;
